styles.content:
/* The scene is the home screen. Utilities live in the floating game menu. */
html,body.dream-play{height:100%;overflow:hidden;overscroll-behavior:none}
body.dream-play{--play-top:var(--shell-top);--play-bottom:var(--shell-bottom);background:#171522}
#dream-stage{top:var(--play-top);bottom:var(--play-bottom);height:auto;z-index:1;border-top:1px solid #a9ead612}
#dream-stage canvas{display:block;width:100%;height:100%;outline-offset:-3px}
#dream-stage #dream-canvas:focus-visible{outline:2px solid #a9ead6}
#dream-stage [data-direction]:focus-visible{outline:2px solid #f3d39c;outline-offset:3px}
#letter-fragments p>small{display:block;margin-bottom:6px;font-size:10px;color:#a7c9b9;letter-spacing:1px}
#dream-stage .stage-vignette{background:linear-gradient(180deg,#15151d70 0,transparent 26%,transparent 80%,#15131f66)}
.stage-reading{display:contents}
#dream-stage .stage-hud{top:15px;left:24px;right:24px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:16px}
#dream-stage .stage-hud-left{gap:13px;align-items:center}
#dream-stage .stage-hud-left>div>span{font-size:9px;letter-spacing:2px;color:#a7a6b2}
#dream-stage .stage-hud-left h2{font-size:19px;letter-spacing:1px;margin-top:3px}
.stage-story-button{display:flex;align-items:center;gap:5px;border:1px solid #b5cbce30;border-radius:20px;padding:7px 10px;font-size:10px;color:#d5d0da;background:#18202999;pointer-events:auto}
.stage-story-button svg{width:14px;height:14px}.stage-story-button:hover{background:#35413e;color:#e6f1dc}
#dream-stage .stage-goals{padding:9px 16px;gap:19px;background:#161b237d;border:1px solid #b2d5cf24;border-radius:25px}
#dream-stage .stage-goals b{font-size:13px}#dream-stage .stage-goals small{font-size:9px}#dream-stage .stage-time{font-size:11px}
#dream-stage .stage-form>span{font-size:12px}#dream-stage .stage-form small{font-size:9px;color:#b1bcb6}
#dream-stage .energy-track{height:4px;width:119px;margin:6px 0 4px auto}
#dream-stage .stage-objective{top:79px;max-width:calc(100% - 36px);width:max-content}
#dream-stage .stage-objective>span{font-size:12px;font-weight:600;color:#e1e5d8}
#dream-stage .stage-objective>small{font-size:11px;color:#bac8bd;margin-top:2px}
#dream-stage .stage-actions{right:24px;bottom:22px}
#dream-stage .stage-desktop-hint{font-size:10px;color:#b8c2bb;left:24px;bottom:27px;gap:10px}
#dream-stage .stage-announcement{top:26%;font-size:13px;background:#1b2129d9;border:1px solid #afc8c335;box-shadow:0 12px 40px #0003;padding:11px 18px;border-radius:12px}
.dream-play .corporate-footer{position:fixed;bottom:0;left:0;right:0;z-index:2;max-width:none;height:var(--play-bottom);margin:0;padding:4px 24px;display:flex;justify-content:center;gap:20px;background:#171522;font-size:9px;line-height:1.6;border-top:1px solid #b9aaca18}
.dream-play .corporate-logo{width:65px;min-height:24px;flex-shrink:0}.dream-play .corporate-logo img{width:65px;height:24px;object-fit:contain}
.dream-play .corporate-legal{display:flex;align-items:center;gap:16px}.dream-play .corporate-legal p+p{margin:0}.dream-play .corporate-legal span{font-size:9px;letter-spacing:0}
.dream-play .corporate-link{margin:0;font-size:9px}
.dream-play .dream-dialog{max-height:calc(100dvh - 32px)}
.dream-play .dialog-eyebrow:empty{display:none}
.dream-play .dream-dialog-close{width:36px;height:36px;top:15px;right:15px;line-height:1}
.dream-play .dream-dialog h2{padding-right:24px}
.map-dialog{width:min(850px,calc(100vw - 32px));padding:28px}
.map-dialog h2{margin:8px 0 18px;font-size:29px}
.map-summary{display:flex;align-items:center;gap:16px;font-size:11px;color:#b4b7ad;margin-bottom:22px}
.map-progress{height:3px;background:#414446;border-radius:3px;flex:1;min-width:30px}
.map-progress i{display:block;height:100%;background:#a9ead6;border-radius:3px}
#dream-save-status{display:flex;align-items:center;gap:5px;font-size:9px;color:#9eb4a8;white-space:nowrap}
#dream-save-status i{width:5px;height:5px;border-radius:50%;background:#a9ead6}
.map-dialog .chapter-grid{gap:12px}
.map-dialog .chapter-card{min-height:165px;padding:16px;border-radius:14px}
.map-dialog .chapter-topline{gap:7px;margin-bottom:14px}
.map-dialog .chapter-number{font-size:8px;letter-spacing:.5px}.map-dialog .chapter-status{font-size:8px;padding:1px 6px}
.map-dialog .chapter-card h3{font-size:19px;max-width:100%;margin-top:1px;position:relative;z-index:2}
.map-dialog .chapter-subtitle{font-size:10px;margin-top:5px;max-width:100%;min-height:16px}
.map-dialog .chapter-card>p{display:none}
.map-dialog .chapter-icon{width:38px;height:38px;right:17px;top:50px;opacity:.18}
.map-dialog .chapter-card:after{width:74px;height:74px;right:0;top:24px}
.map-dialog .chapter-bottom{padding-top:12px;margin-top:auto;gap:6px}.map-dialog .chapter-stars svg{width:11px;height:11px}
.map-dialog .chapter-memories{font-size:8px}.map-dialog .chapter-memories svg{width:11px;height:11px}
.map-dialog .dialog-note{font-size:10px;margin:16px 0}.map-dialog #map-continue{margin-left:auto}
.profile-identity{display:flex;align-items:center;gap:15px;margin:14px 0 20px;padding:12px 15px;background:#35354169;border:1px solid #b2c6ba24;border-radius:14px}
.profile-identity img{width:65px;height:65px}.profile-identity>div{display:flex;flex-direction:column;gap:5px}.profile-identity strong{font-size:18px;color:#f3d8b3}.profile-identity>div>span{font-size:11px;color:#a9afa8}.profile-local{margin-left:auto;font-size:9px;color:#a5baad;border:1px solid #91b49d40;border-radius:20px;padding:3px 7px;white-space:nowrap}
.dream-play .journal-intro{display:none}.dream-play .journal-dialog h2{margin-top:9px}
.dream-play .journal-stats{margin-top:0}
.dream-play .pause-dialog .dialog-eyebrow{display:none}.dream-play .pause-dialog h2{padding-right:0}
.dream-play .pause-dialog #pause-detail{font-size:12px}
.dream-play .dream-toast{bottom:calc(var(--play-bottom) + 18px);z-index:500}
@media(max-width:800px){
  #dream-stage .stage-hud{left:16px;right:16px;gap:10px}
  #dream-stage .stage-hud-left h2{font-size:16px}
  #dream-stage .stage-goals{gap:10px;padding:8px 12px}#dream-stage .stage-goals small{display:none}
  #dream-stage .stage-goals b{font-size:12px}#dream-stage .stage-goals svg{width:14px;height:14px}
  #dream-stage .stage-form>span{font-size:10px}
  .stage-story-button{padding:6px 8px;font-size:9px}
  .dream-play .corporate-footer{padding:4px 14px;gap:14px}.dream-play .corporate-legal{gap:12px;font-size:8px}.dream-play .corporate-link{font-size:8px}.dream-play .corporate-legal span{font-size:8px}
}
@media(max-width:640px){
  #dream-stage{background:linear-gradient(180deg,#11252b,#141d29)}
  #dream-stage canvas{height:calc(100% - 112px)}
  /* Real rows reserve the status height. The next instruction and any cap
     dialogue follow their actual text height, including large system fonts. */
  #dream-stage .stage-reading{position:absolute;top:10px;left:14px;right:14px;display:grid;grid-template-columns:minmax(0,1fr);gap:8px;pointer-events:none}
  #dream-stage .stage-reading .stage-hud{position:static;inset:auto;grid-template-columns:minmax(0,1fr) auto;gap:6px 10px;align-items:center;min-width:0}
  #dream-stage .stage-reading .stage-hud-left{gap:10px;grid-column:1;grid-row:1;align-items:center;min-width:0}
  #dream-stage .stage-hud-left>div{min-width:0}
  #dream-stage .stage-hud-left h2{font-size:16px;letter-spacing:0;margin-top:2px;overflow-wrap:anywhere}
  #dream-stage .stage-hud-left>div>span{font-size:8px;letter-spacing:1px}
  .stage-story-button{font-size:11px;padding:6px 8px;gap:4px;min-height:36px;flex:none;align-self:center}.stage-story-button svg{width:13px;height:13px}
  #dream-stage .stage-reading .stage-goals{grid-column:2;grid-row:1;justify-self:end;gap:9px;border:0;background:none;padding:4px 0}
  #dream-stage .stage-goals>span{gap:4px}#dream-stage .stage-goals b{font-size:12px}
  #dream-stage .stage-time{display:none}
  /* The compact counters still name their categories to assistive reading. */
  #dream-stage .stage-reading .stage-goals small{display:block;position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
  #dream-stage .stage-reading .stage-form{display:grid;grid-template-columns:auto minmax(44px,1fr) auto;grid-column:1/-1;grid-row:2;align-items:center;column-gap:8px;min-width:0;max-width:none;justify-self:stretch;text-align:left;transform:none}
  #dream-stage .stage-reading .stage-form>span{font-size:11px;line-height:1.4;white-space:nowrap}
  #dream-stage .stage-reading #stage-energy-label{display:block;font-size:11px;line-height:1.4;white-space:nowrap;text-align:right;color:#c1cec5}
  #dream-stage .stage-reading .energy-track{width:100%;height:4px;margin:0}
  #dream-stage .stage-reading .stage-objective,
  .lost-inspecting #dream-stage .stage-reading .stage-objective{position:static;inset:auto;transform:none;width:auto;min-width:0;max-width:none;margin:0;text-align:left}
  #dream-stage .stage-reading #stage-objective{font-size:11px;line-height:1.6;font-weight:500;color:#c6d0c6}
  #dream-stage .stage-reading #stage-near-hint{font-size:11px;line-height:1.55;font-weight:600;margin-top:4px;max-width:none;color:#edf1df}
  #dream-stage .stage-reading #stage-cap-activity{gap:6px;max-width:100%;font-size:10px;line-height:1.5;padding:4px 8px;margin:6px 0 0;box-shadow:none}
  #dream-stage .stage-reading #stage-cap-activity-name{min-width:0;white-space:normal;overflow-wrap:anywhere}
  #dream-stage .stage-reading #stage-cap-activity-count{flex:none;font-size:10px;white-space:nowrap}
  #dream-stage .stage-reading #stage-cap-activity-progress,
  #dream-stage .stage-reading #stage-cap-activity>i{display:none}
  #dream-stage .stage-reading #stage-lost-case{max-width:100%;font-size:10px;white-space:normal;overflow-wrap:anywhere}
  #dream-stage .stage-announcement{top:29%;font-size:11px;width:auto;max-width:calc(100% - 42px);padding:10px 12px;white-space:normal;text-align:center}
  #dream-stage .stage-touch-move{display:grid;left:14px;bottom:17px;width:123px;height:123px;padding:0}
  #dream-stage .stage-touch-move>button{font-size:22px}
  #dream-stage .stage-actions{right:14px;bottom:20px;gap:8px}
  #dream-stage .stage-action{min-width:67px;width:67px;height:67px;border-radius:17px}
  #dream-stage .stage-action>span:not(.action-glyph){font-size:9px}
  #dream-stage .secondary-action{height:36px;top:-45px;border-radius:12px}
  #dream-stage .stage-desktop-hint{display:none}
  .dream-play .corporate-footer{gap:12px;justify-content:center;align-items:center;padding:4px 12px 6px}
  .dream-play .corporate-logo,.dream-play .corporate-logo img{width:49px;height:25px;min-height:0}
  .dream-play .corporate-legal{display:block;text-align:left;font-size:8px;line-height:1.8}
  .dream-play .corporate-legal p:first-child{letter-spacing:0}.dream-play .corporate-legal p+p{margin:0}
  .dream-play .corporate-legal span{font-size:8px}.dream-play .corporate-link{display:none}
  .map-dialog{padding:23px 18px}.map-dialog h2{font-size:24px;margin:7px 0 18px}
  .map-summary{gap:9px;font-size:10px;flex-wrap:wrap;margin-bottom:16px}.map-summary #dream-save-status{font-size:8px}
  .map-dialog .chapter-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
  .map-dialog .chapter-card{padding:12px;min-height:148px}.map-dialog .chapter-number{font-size:6px}.map-dialog .chapter-status{font-size:6px;padding:1px 4px}
  .map-dialog .chapter-topline{margin-bottom:13px;gap:4px}.map-dialog .chapter-card h3{font-size:17px}.map-dialog .chapter-subtitle{font-size:8px;line-height:1.65}
  .map-dialog .chapter-bottom{gap:4px;padding-top:10px}.map-dialog .chapter-stars{gap:1px}.map-dialog .chapter-stars svg{width:9px;height:9px}.map-dialog .chapter-memories{font-size:7px}.map-dialog .chapter-arrow{width:11px;height:11px}
  .map-dialog .dialog-note{font-size:9px}.map-dialog #map-continue{width:100%}
  .profile-identity{gap:10px;padding:10px;margin-bottom:15px}.profile-identity img{width:52px;height:52px}.profile-identity strong{font-size:16px}.profile-identity>div>span{font-size:9px}.profile-local{font-size:8px;padding:3px 6px}
  .dream-play .dream-dialog-close{top:9px;right:9px;width:36px;height:36px}
}
@media(max-width:360px){
  #dream-stage .stage-touch-move{left:10px;width:113px;height:113px}
  #dream-stage .stage-actions{right:10px;gap:6px}#dream-stage .stage-action{width:62px;min-width:62px;height:64px}#dream-stage .secondary-action{height:35px}
  .dream-play .corporate-footer{gap:8px;padding-left:8px;padding-right:8px}.dream-play .corporate-logo,.dream-play .corporate-logo img{width:38px}
}
@media(max-height:520px) and (min-width:601px){
  #dream-stage .stage-hud{top:8px}.stage-story-button{padding:5px 8px}
  #dream-stage .stage-objective{top:52px}#dream-stage .stage-objective>span{font-size:10px}#dream-stage .stage-objective>small{font-size:9px}
  #dream-stage .stage-actions{bottom:12px;right:17px}#dream-stage .stage-touch-move{bottom:12px;width:97px;height:97px}
  #dream-stage .stage-desktop-hint{bottom:16px;font-size:8px}
}

@media(max-width:640px){body.dream-play>.corporate-footer{padding-bottom:calc(6px + env(safe-area-inset-bottom,0px))}}

/* The lid, its small world, and the two friends remain the focus. */
.cap-bubble{position:absolute;left:50%;bottom:112px;transform:translate(-50%,8px);z-index:6;width:max-content;max-width:min(470px,calc(100% - 36px));display:flex;align-items:center;gap:13px;padding:13px 18px 13px 12px;border:1px solid #e6ca9b55;border-radius:18px;background:#242234ee;box-shadow:0 12px 45px #08091444;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .2s,transform .25s;backdrop-filter:blur(10px)}
.cap-bubble.show{opacity:1;visibility:visible;transform:translate(-50%,0)}.cap-bubble>img{width:49px;height:49px;flex:none;filter:drop-shadow(0 0 9px #b5edd522)}.cap-bubble-lines{display:flex;flex-direction:column;gap:5px}.cap-bubble p{margin:0;font-size:12px;line-height:1.75;color:#eee5d4}.cap-bubble b{font-size:10px;color:#d5ba94;margin-right:8px;font-weight:500}.cap-bubble p[data-speaker="light"] b{color:#a9dfcc}.cap-bubble:after{content:"";position:absolute;bottom:-7px;left:44px;width:12px;height:12px;transform:rotate(45deg);border-right:1px solid #e6ca9b55;border-bottom:1px solid #e6ca9b55;background:#242234}
.cap-status{display:flex;align-items:center;justify-content:flex-end;gap:5px;margin-top:4px;color:#e1c7a0;font-size:8px;min-height:12px}.cap-status i{display:inline-block;width:3px;height:3px;border-radius:50%;background:#bfe9d6;box-shadow:0 0 6px #bfe9d666}.cap-status[data-phase="closed"]{color:#a8b9b2}.cap-status[data-phase="returning"] i{background:#e7bb8a}
.journal-cap-link{display:flex;align-items:center;gap:13px;width:100%;text-align:left;border:1px solid #e0c39d40;border-radius:13px;background:linear-gradient(100deg,#9c84be15,#a6d7bd08);color:#eee0c9;padding:11px 14px;margin:0 0 11px;cursor:pointer;font-family:inherit}.journal-cap-link img{width:48px;height:48px}.journal-cap-link>span{display:flex;flex-direction:column;gap:5px}.journal-cap-link strong{font-size:13px;font-weight:500}.journal-cap-link small{font-size:10px;color:#b7b6bd}.journal-cap-link>i{font-style:normal;margin-left:auto;color:#e2c395}.journal-cap-link:hover{border-color:#e6c49388;background:#b5a0ce18}
.cap-book-dialog{width:min(850px,calc(100vw - 32px));padding:30px;max-height:calc(100dvh - 32px);color:#eadfcd;background:#242131}.cap-book-dialog h2{font-size:28px;line-height:1.4;margin:9px 0 17px}.cap-book-stats{display:flex;align-items:center;gap:25px;border-bottom:1px solid #c7b8cd20;padding-bottom:18px;margin-bottom:21px}.cap-book-stats b{font-size:20px;color:#e4c99e;font-weight:500;letter-spacing:.5px}.cap-book-stats>span{display:flex;gap:7px;align-items:baseline;font-size:10px;color:#afa8ba}.cap-book-feature{display:grid;grid-template-columns:275px minmax(0,1fr);column-gap:25px;border:1px solid #cbb7d32c;border-radius:19px;background:radial-gradient(ellipse at 22% 25%,#678b7c15,transparent 62%),#1b1b2a66;overflow:hidden}.cap-book-window{display:flex;align-items:center;justify-content:center;min-height:270px;position:relative;isolation:isolate}.cap-book-window:before{content:"";position:absolute;width:215px;height:215px;border:1px dashed #dec3a028;border-radius:50%;z-index:-1;transform:translate(4px,0)}.cap-book-window canvas{display:block;width:275px;height:228px;max-width:100%;filter:drop-shadow(0 10px 10px #08081133)}.cap-book-window.unopened{flex-direction:column;gap:10px}.cap-book-window.unopened img{width:175px;height:175px;filter:saturate(.6);opacity:.75}.cap-book-window.unopened>span{font-size:10px;color:#b9b1c3}.cap-book-copy{padding:30px 22px 22px 0;display:flex;flex-direction:column;justify-content:center}.cap-book-copy>small{font-size:10px;color:var(--cap-accent);letter-spacing:1px}.cap-book-copy h3{font-size:24px;line-height:1.4;color:#f0debc;margin:8px 0;font-weight:550}.cap-book-copy>p{font-size:11px;line-height:1.85;color:#b9b3c1;margin:0 0 12px}.cap-book-lines{border-left:2px solid #c2d8b54a;padding-left:12px;margin-bottom:15px}.cap-book-lines p{margin:4px 0;font-size:11px;line-height:1.8;color:#d7cfdd}.cap-book-lines b{font-size:9px;color:#d5b88c;margin-right:8px;font-weight:400}.cap-book-actions{display:flex;align-items:center;gap:15px;flex-wrap:wrap}.cap-book-actions .dream-secondary{font-size:11px;min-height:36px;padding:7px 12px}.cap-book-actions .dream-text-link{font-size:10px}.cap-thoughts{grid-column:1/-1;border-top:1px solid #cbb7d320;padding:17px 22px 20px;background:#17182338}.cap-thoughts-title{display:flex;justify-content:space-between;font-size:10px;color:#c6bea7;margin-bottom:12px}.cap-thoughts-title b{font-weight:400;color:#d4c2a6}.cap-thoughts-title span{color:#aaa0b5}.cap-thought{display:flex;align-items:flex-start;gap:10px;padding:8px 0;color:#827d91}.cap-thought>i{width:17px;flex:none;font-style:normal;font-size:14px;color:#736c85}.cap-thought small{font-size:9px;color:#9690a2}.cap-thought p{font-size:11px;line-height:1.8;margin:4px 0 0}.cap-thought.found{color:#d8d1c6}.cap-thought.found>i{color:#edc991}.cap-thought.found small{color:#d6b68a}.cap-book-section-title{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:26px 0 13px}.cap-book-section-title h3{font-size:13px;font-weight:500;color:#dfcfb6}.cap-book-section-title>span{font-size:9px;color:#a39bb2}.cap-book-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px}.cap-book-card{display:flex;align-items:center;gap:8px;text-align:left;border:1px solid #c1adc024;background:#ffffff02;border-radius:12px;padding:9px;font-family:inherit;color:#cfc4d3;cursor:pointer;transition:background .2s,border-color .2s;min-width:0}.cap-book-card img{width:49px;height:49px;filter:grayscale(.8);opacity:.4;flex:none}.cap-book-card>span{min-width:0;display:flex;flex-direction:column;gap:4px}.cap-book-card small{font-size:8px;color:#9b90a6}.cap-book-card b{font-size:10px;font-weight:500;line-height:1.5;color:#bbb1c4}.cap-book-card em{font-size:8px;font-style:normal;color:#8f879d}.cap-book-card.discovered img{filter:none;opacity:1}.cap-book-card.discovered b{color:#eed7b3}.cap-book-card.discovered em{color:#a9cbb8}.cap-book-card:hover,.cap-book-card.selected{border-color:#d9ba8066;background:#bda7860a}.cap-book-card:focus-visible{outline:2px solid #e6c28c;outline-offset:2px}
